package main

import (
	"database/sql"
	"log"
	"net/http"

	"linkshelf/internal/api"
	"linkshelf/internal/store"

	_ "github.com/mattn/go-sqlite3"
)

func main() {
	db, err := sql.Open("sqlite3", "linkshelf.db")
	if err != nil {
		log.Fatalf("failed to open database: %v", err)
	}
	defer db.Close()

	if err := store.InitSchema(db); err != nil {
		log.Fatalf("failed to init schema: %v", err)
	}

	store.DB = db

	mux := http.NewServeMux()
	mux.HandleFunc("/", api.HandleGetRoot)
	mux.HandleFunc("/static/", api.HandleGetStatic)
	mux.HandleFunc("/api/links", func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodGet:
			api.HandleListLinks(w, r)
		case http.MethodPost:
			api.HandleCreateLink(w, r)
		default:
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		}
	})
	mux.HandleFunc("/api/links/", api.HandleDeleteLink)

	log.Println("Listening on :8080")
	if err := http.ListenAndServe(":8080", mux); err != nil {
		log.Fatalf("server error: %v", err)
	}
}

