package main

import (
	"database/sql"
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"os"
	"strings"
	"testing"

	"linkshelf/internal/api"
	"linkshelf/internal/store"
)

func TestMainRoutes(t *testing.T) {
	// Change to project root so web/index.html can be found
	origDir, err := os.Getwd()
	if err != nil {
		t.Fatal(err)
	}
	if err := os.Chdir("../../"); err != nil {
		t.Fatal(err)
	}
	defer os.Chdir(origDir)

	// Set up in-memory database
	db := setupTestDB(t)
	defer db.Close()

	store.DB = db

	mux := http.NewServeMux()
	mux.HandleFunc("/", api.HandleGetRoot)
	mux.HandleFunc("/api/links", func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodGet:
			api.HandleListLinks(w, r)
		case http.MethodPost:
			api.HandleCreateLink(w, r)
		default:
			http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		}
	})
	mux.HandleFunc("/api/links/", api.HandleDeleteLink)

	ts := httptest.NewServer(mux)
	defer ts.Close()

	t.Run("GET / returns 200", func(t *testing.T) {
		resp, err := http.Get(ts.URL + "/")
		if err != nil {
			t.Fatal(err)
		}
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Errorf("expected 200, got %d", resp.StatusCode)
		}
	})

	t.Run("GET /api/links returns empty list", func(t *testing.T) {
		resp, err := http.Get(ts.URL + "/api/links")
		if err != nil {
			t.Fatal(err)
		}
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Errorf("expected 200, got %d", resp.StatusCode)
		}
		var links []store.Link
		if err := json.NewDecoder(resp.Body).Decode(&links); err != nil {
			t.Fatal(err)
		}
		if len(links) != 0 {
			t.Errorf("expected empty list, got %d items", len(links))
		}
	})

	t.Run("POST /api/links creates a link", func(t *testing.T) {
		body := `{"url":"https://example.com","title":"Example"}`
		resp, err := http.Post(ts.URL+"/api/links", "application/json", strings.NewReader(body))
		if err != nil {
			t.Fatal(err)
		}
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusCreated {
			t.Errorf("expected 201, got %d", resp.StatusCode)
		}
	})

	t.Run("POST /api/links with invalid body returns 400", func(t *testing.T) {
		body := `invalid`
		resp, err := http.Post(ts.URL+"/api/links", "application/json", strings.NewReader(body))
		if err != nil {
			t.Fatal(err)
		}
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusBadRequest {
			t.Errorf("expected 400, got %d", resp.StatusCode)
		}
	})

	t.Run("DELETE /api/links/ with no ID returns 400", func(t *testing.T) {
		req, err := http.NewRequest(http.MethodDelete, ts.URL+"/api/links/", nil)
		if err != nil {
			t.Fatal(err)
		}
		resp, err := http.DefaultClient.Do(req)
		if err != nil {
			t.Fatal(err)
		}
		defer resp.Body.Close()
		// trailing slash with no ID - should be 400 or 404
		if resp.StatusCode != http.StatusBadRequest && resp.StatusCode != http.StatusNotFound {
			t.Errorf("expected 400 or 404, got %d", resp.StatusCode)
		}
	})
}

func setupTestDB(t *testing.T) *sql.DB {
	t.Helper()
	db, err := sql.Open("sqlite3", ":memory:")
	if err != nil {
		t.Fatalf("failed to open in-memory db: %v", err)
	}
	if err := store.InitSchema(db); err != nil {
		t.Fatalf("failed to init schema: %v", err)
	}
	return db
}

