/* Base reset and typography */
* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

body {
  font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
  background: #f5f5f5;
  color: #333;
  line-height: 1.6;
}

.container {
  max-width: 800px;
  margin: 2rem auto;
  padding: 0 1rem;
}

/* Header */
h1 {
  text-align: center;
  margin-bottom: 1.5rem;
  color: #2c3e50;
}

/* Link form */
.link-form {
  display: flex;
  gap: 0.5rem;
  margin-bottom: 2rem;
  flex-wrap: wrap;
}

.link-form input,
.link-form button {
  padding: 0.6rem 1rem;
  font-size: 1rem;
  border: 1px solid #ccc;
  border-radius: 4px;
}

.link-form input {
  flex: 1 1 200px;
}

.link-form input:focus {
  outline: none;
  border-color: #3498db;
}

.link-form button {
  background: #3498db;
  color: #fff;
  border: none;
  cursor: pointer;
  transition: background 0.2s;
}

.link-form button:hover {
  background: #2980b9;
}

/* Link list */
.link-list {
  list-style: none;
}

.link-item {
  background: #fff;
  border: 1px solid #e0e0e0;
  border-radius: 4px;
  padding: 1rem;
  margin-bottom: 0.75rem;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.link-item a {
  color: #3498db;
  text-decoration: none;
  font-weight: 500;
}

.link-item a:hover {
  text-decoration: underline;
}

.link-item .delete-btn {
  background: #e74c3c;
  color: #fff;
  border: none;
  padding: 0.4rem 0.8rem;
  border-radius: 4px;
  cursor: pointer;
  font-size: 0.875rem;
  transition: background 0.2s;
}

.link-item .delete-btn:hover {
  background: #c0392b;
}
